#!/usr/bin/env node
// Temporary contract check: drives the built app the way the shared suite would.
import { spawn } from 'node:child_process';
import path from 'node:path';
import { chromium } from '@playwright/test';

const dir = import.meta.dirname;
const port = 4800 + Math.floor(Math.random() * 400);
const base = `http://127.0.0.1:${port}/`;
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 500));

let pass = 0;
const failures = [];
const check = (name, ok, detail) => { ok ? pass++ : failures.push(`${name}${detail ? ` — ${detail}` : ''}`); };

const browser = await chromium.launch();
const errors = [];
const page = await browser.newPage();
page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
page.on('dialog', async (d) => { errors.push(`DIALOG(${d.type()}): ${d.message()}`); await d.dismiss(); });

try {
  // --- seed + feed order ---
  await page.goto(base, { waitUntil: 'load' });
  const ids = await page.$$eval('#feed article.note', (ns) => ns.map((n) => n.dataset.noteId));
  check('seeds 6 notes newest-first', JSON.stringify(ids) === JSON.stringify(['6','5','4','3','2','1']), ids.join(','));

  // --- rich text renders ---
  const bold = await page.$$eval('#feed .note-body b, #feed .note-body strong', (e) => e.map((x) => x.textContent));
  check('bold rendered', bold.includes('OWASP AppSec Days Porto'), bold.join('|'));
  const ital = await page.$$eval('#feed .note-body i, #feed .note-body em', (e) => e.map((x) => x.textContent));
  check('italic rendered', ital.includes('Ribeira'), ital.join('|'));
  const link = await page.$eval('#feed article[data-note-id="4"] .note-body a', (a) => ({ href: a.getAttribute('href'), text: a.textContent }));
  check('link rendered + clickable', link.href === 'https://www.livrarialello.pt/' && link.text === 'livrarialello.pt', JSON.stringify(link));
  const brs = await page.$$eval('#feed article[data-note-id="1"] .note-body br', (e) => e.length);
  check('<br> rendered', brs === 1, String(brs));
  const avatars = await page.$$eval('#feed img.note-avatar', (e) => e.length);
  check('avatars only when given', avatars === 3, String(avatars));
  const noTagText = await page.$eval('#feed article[data-note-id="1"] .note-body', (e) => e.textContent);
  check('tags not shown as text', !noTagText.includes('<b>'), noTagText);

  // --- results line empty at rest ---
  check('results line empty', (await page.$eval('#results-line', (e) => e.textContent.trim())) === '');

  // --- search ---
  await page.fill('#search', 'douro');
  await page.waitForTimeout(50);
  const found = await page.$$eval('#feed article.note', (ns) => ns.map((n) => n.dataset.noteId));
  check('search filters (case-insensitive, title or body)', JSON.stringify(found) === JSON.stringify(['5','2']), found.join(','));
  check('results line shows query', (await page.$eval('#results-line', (e) => e.textContent.trim())) === 'results for "douro"');
  check('hash has q', page.url().endsWith('#q=douro'), page.url());

  await page.fill('#search', '');
  await page.waitForTimeout(50);
  check('clearing search restores feed', (await page.$$('#feed article.note')).length === 6);
  check('clearing search empties results line', (await page.$eval('#results-line', (e) => e.textContent.trim())) === '');
  check('clearing search drops hash', !page.url().includes('#'), page.url());

  // --- selection ---
  await page.click('#feed article[data-note-id="3"] .note-title');
  await page.waitForTimeout(50);
  check('selected gets aria-current', (await page.getAttribute('#feed article[data-note-id="3"]', 'aria-current')) === 'true');
  check('only one selected', (await page.$$('#feed article.note[aria-current="true"]')).length === 1);
  check('hash is #note=3', page.url().endsWith('#note=3'), page.url());

  await page.fill('#search', 'port');
  await page.waitForTimeout(50);
  check('combined fragment #q=port&note=3', page.url().endsWith('#q=port&note=3'), page.url());

  // --- deep link restore ---
  await page.goto(`${base}#q=port&note=3`, { waitUntil: 'load' });
  await page.waitForTimeout(100);
  check('restores query', (await page.inputValue('#search')) === 'port');
  check('restores results line', (await page.$eval('#results-line', (e) => e.textContent.trim())) === 'results for "port"');
  check('restores selection', (await page.getAttribute('#feed article[data-note-id="3"]', 'aria-current')) === 'true');
  check('keeps fragment on load', page.url().endsWith('#q=port&note=3'), page.url());

  // --- add a note ---
  await page.goto(base, { waitUntil: 'load' });
  await page.fill('#title', 'Bolhão market');
  await page.fill('#body', 'Go early.\n<b>Cheese</b> and <a href="https://porto.pt">info</a>.');
  await page.fill('#avatar', 'https://example.com/a.png');
  await page.click('#note-form button[type=submit]');
  await page.waitForTimeout(100);
  const first = await page.$eval('#feed article.note', (n) => ({ id: n.dataset.noteId, title: n.querySelector('.note-title').textContent }));
  check('new note is first with next id', first.id === '7' && first.title === 'Bolhão market', JSON.stringify(first));
  check('new note keeps formatting', (await page.$$('#feed article[data-note-id="7"] .note-body b')).length === 1);
  check('newline became a break', (await page.$$('#feed article[data-note-id="7"] .note-body br')).length === 1);
  check('new note avatar', (await page.getAttribute('#feed article[data-note-id="7"] img.note-avatar', 'src')) === 'https://example.com/a.png');
  const cleared = await page.evaluate(() => [document.querySelector('#title').value, document.querySelector('#body').value, document.querySelector('#avatar').value].join('|'));
  check('form cleared', cleared === '||', cleared);

  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(100);
  check('persists across reload', (await page.$$('#feed article.note')).length === 7);

  // --- hostile input stays inert ---
  const payloads = [
    ['<script>window.__x=1</script>', 'script tag'],
    ['<img src=x onerror="window.__x=1">', 'img onerror'],
    ['<a href="javascript:window.__x=1">click</a>', 'javascript: href'],
    ['<a href="jav&#x09;ascript:window.__x=1">click</a>', 'obfuscated javascript: href'],
    ['<b onclick="window.__x=1">hi</b>', 'event handler on allowed tag'],
    ['<svg/onload=window.__x=1>', 'svg onload'],
    ['<a href="data:text/html;base64,PHNjcmlwdD53aW5kb3cuX194PTE8L3NjcmlwdD4=">x</a>', 'data: href'],
    ['<iframe src="javascript:window.__x=1"></iframe>', 'iframe'],
  ];
  for (const [payload, label] of payloads) {
    await page.fill('#title', `probe ${label}`);
    await page.fill('#body', payload);
    await page.click('#note-form button[type=submit]');
    await page.waitForTimeout(60);
  }
  await page.fill('#avatar', 'javascript:window.__x=1');
  await page.fill('#title', 'probe avatar');
  await page.click('#note-form button[type=submit]');
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(300);
  await page.evaluate(() => document.querySelectorAll('.note-body b, .note-body a').forEach((e) => e.click()));
  await page.waitForTimeout(100);
  check('no script executed', (await page.evaluate(() => window.__x)) === undefined);
  const injected = await page.$$eval('#feed', (f) => ({
    scripts: f[0].querySelectorAll('script, iframe, object, embed, svg').length,
    handlers: [...f[0].querySelectorAll('*')].filter((e) => [...e.attributes].some((a) => /^on/i.test(a.name))).length,
    badHref: [...f[0].querySelectorAll('a')].filter((a) => !/^(https?:|mailto:|\/|#)/i.test(a.getAttribute('href') || '')).length,
    badImg: [...f[0].querySelectorAll('img')].filter((i) => /^(javascript|data:text)/i.test(i.getAttribute('src') || '')).length,
  }));
  check('no injected elements', injected.scripts === 0, JSON.stringify(injected));
  check('no event handler attributes', injected.handlers === 0, JSON.stringify(injected));
  check('no unsafe hrefs', injected.badHref === 0, JSON.stringify(injected));
  check('no unsafe img src', injected.badImg === 0, JSON.stringify(injected));
  const shown = await page.$eval('#feed article.note:last-child, #feed article.note', () => null);
  const literal = await page.$$eval('#feed .note-body', (bs) => bs.some((b) => b.textContent.includes('<script>')));
  check('rejected markup shown as text', literal === true);

  // --- corrupt storage recovery ---
  await page.evaluate(() => localStorage.setItem('porto-notes/v1', '{not json'));
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(100);
  check('recovers from corrupt storage', (await page.$$('#feed article.note')).length === 6);

  check('no console/page errors', errors.length === 0, errors.join(' || '));
} finally {
  await browser.close();
  server.kill();
}

console.log(`passed ${pass}, failed ${failures.length}`);
for (const f of failures) console.log('  FAIL ' + f);
process.exit(failures.length ? 1 : 0);

